INSERT INTO `posts` (`id`, `user_id`, `title`, `sku`, `description`, `status`, `type`, `created_at`, `updated_at`) VALUES
(1, 1, 'About Us', 'about-us', '<h2>Welcome to NestifyTech</h2><p>NestifyTech is your trusted destination for premium electronics, smart devices, and cutting-edge gadgets. We are passionate about connecting people with technology that enhances their lives.</p><h3>Our Mission</h3><p>Our mission is simple: to offer authentic, high-quality technology products at competitive prices, backed by exceptional customer service. We carefully curate every item in our catalog to ensure it meets our high standards.</p><h3>Why Choose NestifyTech?</h3><ul><li><strong>Genuine Products:</strong> Every product is 100% authentic and sourced from verified manufacturers.</li><li><strong>Expert Support:</strong> Our team of tech experts is available 24/7 to assist you.</li><li><strong>Fast Shipping:</strong> We partner with reliable logistics providers for speedy delivery.</li><li><strong>Easy Returns:</strong> Hassle-free 30-day return policy on all orders.</li></ul><h3>Our Story</h3><p>Founded with a vision to democratize access to premium technology, NestifyTech has grown from a small online store to a trusted marketplace serving thousands of customers. We believe everyone deserves access to great technology.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:19:45'),
(2, 1, 'Privacy Policy', 'privacy-policy', '<h2>Privacy Policy</h2><p><strong>Last Updated: January 2025</strong></p><p>At NestifyTech, we are committed to protecting your privacy. This Privacy Policy explains how we collect, use, and safeguard your personal information when you visit our website or make a purchase.</p><h3>Information We Collect</h3><ul><li><strong>Personal Information:</strong> Name, email address, phone number, and shipping address when you create an account or place an order.</li><li><strong>Payment Information:</strong> We use secure third-party payment processors and do not store your full payment card details.</li><li><strong>Usage Data:</strong> Browser type, IP address, pages visited, and time spent on our site to improve user experience.</li></ul><h3>How We Use Your Information</h3><ul><li>To process and fulfill your orders</li><li>To send order confirmations and shipping updates</li><li>To improve our website and product offerings</li><li>To send promotional emails (with your consent)</li><li>To comply with legal obligations</li></ul><h3>Data Security</h3><p>We implement industry-standard security measures including SSL encryption to protect your data. However, no method of transmission over the Internet is 100% secure.</p><h3>Your Rights</h3><p>You have the right to access, correct, or delete your personal data. Contact us at privacy@nestifytech.com to exercise these rights.</p><h3>Contact Us</h3><p>If you have questions about this Privacy Policy, please contact us at privacy@nestifytech.com.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:19:12'),
(3, 1, 'Terms & Conditions', 'terms-conditions', '<h2>Terms &amp; Conditions</h2><p><strong>Last Updated: January 2025</strong></p><p>Please read these Terms and Conditions carefully before using NestifyTech. By accessing our website or placing an order, you agree to be bound by these terms.</p><h3>Use of Website</h3><p>You must be at least 18 years old to use our services. You agree not to use the site for any unlawful purpose or in a way that violates these terms.</p><h3>Orders &amp; Payments</h3><ul><li>All orders are subject to product availability.</li><li>Prices are subject to change without notice.</li><li>Payment must be received in full before orders are processed.</li><li>We reserve the right to cancel any order for any reason.</li></ul><h3>Shipping &amp; Delivery</h3><p>Shipping times are estimates only. NestifyTech is not responsible for delays caused by carriers or customs. Risk of loss passes to you upon delivery.</p><h3>Returns &amp; Refunds</h3><p>We offer a 30-day return policy on most items. Products must be in original condition. Please see our Return Policy for full details.</p><h3>Intellectual Property</h3><p>All content on this website, including images, text, and logos, is the property of NestifyTech and may not be used without permission.</p><h3>Limitation of Liability</h3><p>NestifyTech is not liable for any indirect, incidental, or consequential damages arising from the use of our products or services.</p><h3>Contact</h3><p>For questions about these terms, contact us at legal@nestifytech.com.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:18:32'),
(4, 1, 'Return & Refund Policy', 'return-refund-policy', '<h2>Return &amp; Refund Policy</h2><p><strong>Last Updated: January 2025</strong></p><p>We want you to be completely satisfied with your purchase. If you are not happy with your order, we offer a straightforward 30-day return and refund policy.</p><h3>Eligibility for Returns</h3><ul><li>Items must be returned within 30 days of delivery.</li><li>Products must be in their original, unused condition with all original packaging.</li><li>Items marked as non-returnable are excluded from this policy.</li></ul><h3>How to Return an Item</h3><ol><li>Log in to your account and navigate to your orders.</li><li>Select the item you wish to return and choose a reason.</li><li>Print the pre-paid return label (where applicable).</li><li>Pack the item securely and drop it off at the nearest courier.</li></ol><h3>Refund Process</h3><p>Once we receive and inspect your returned item, we will process your refund within 5–7 business days. Refunds are issued to the original payment method.</p><h3>Damaged or Defective Items</h3><p>If you receive a damaged or defective item, contact us within 48 hours of delivery with photos at support@nestifytech.com. We will arrange a replacement or full refund.</p><h3>Contact Us</h3><p>For questions about returns, email returns@nestifytech.com or call our support line.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:17:29'),
(5, 1, 'Shipping Policy', 'shipping-policy', '<h2>Shipping Policy</h2><p><strong>Last Updated: January 2025</strong></p><p>We strive to deliver your orders as quickly and reliably as possible. Here is everything you need to know about our shipping process.</p><h3>Processing Time</h3><p>Orders are typically processed within 1–2 business days after payment confirmation. Orders placed on weekends or public holidays are processed the next business day.</p><h3>Shipping Options</h3><ul><li><strong>Standard Shipping:</strong> 5–7 business days</li><li><strong>Express Shipping:</strong> 2–3 business days</li><li><strong>Same-Day Delivery:</strong> Available in select cities</li></ul><h3>Shipping Costs</h3><p>Shipping costs are calculated at checkout based on your location and chosen shipping method. Orders above a certain threshold may qualify for free shipping — check our promotions page.</p><h3>Order Tracking</h3><p>Once your order ships, you will receive an email with a tracking number. Use this to monitor your shipment\'s progress.</p><h3>International Shipping</h3><p>We ship to select international destinations. Additional customs duties and taxes may apply and are the responsibility of the customer.</p><h3>Contact Us</h3><p>For shipping inquiries, email shipping@nestifytech.com.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:16:51'),
(6, 1, 'Contact Us', 'contact-us', '<h2>Get in Touch</h2><p>We love hearing from our customers! Whether you have a question about your order, need technical support, or just want to share feedback — our team is here to help.</p><h3>Customer Support Hours</h3><ul><li><strong>Monday – Friday:</strong> 9:00 AM – 8:00 PM</li><li><strong>Saturday:</strong> 10:00 AM – 6:00 PM</li><li><strong>Sunday:</strong> 12:00 PM – 5:00 PM</li></ul><h3>Contact Channels</h3><ul><li><strong>Email:</strong> support@nestifytech.com</li><li><strong>Phone:</strong> +92 321 808 6139</li><li><strong>Live Chat:</strong> Available on our website during business hours</li><li><strong>WhatsApp:</strong> +92 321 808 6139</li></ul><h3>Visit Us</h3><p>NestifyTech HQ</p><p>123 Tech Avenue, Digital Park</p><p>Islamabad, Pakistan</p><h3>Send a Message</h3><p>Fill out the contact form below and our team will get back to you within 24 hours.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:16:09'),
(7, 1, 'Cookie Policy', 'cookie-policy', '<h2>Cookie Policy</h2><p><strong>Last Updated: January 2025</strong></p><p>This Cookie Policy explains how NestifyTech uses cookies and similar tracking technologies when you visit our website.</p><h3>What Are Cookies?</h3><p>Cookies are small text files placed on your device when you visit a website. They help the site remember your preferences, login status, and browsing behavior to enhance your experience.</p><h3>Types of Cookies We Use</h3><ul><li><strong>Essential Cookies:</strong> Required for the website to function properly (e.g., shopping cart, login sessions).</li><li><strong>Analytics Cookies:</strong> Help us understand how visitors use our site so we can improve it.</li><li><strong>Marketing Cookies:</strong> Used to deliver relevant advertisements based on your interests.</li><li><strong>Preference Cookies:</strong> Remember your settings like language and currency.</li></ul><h3>Managing Cookies</h3><p>You can control cookies through your browser settings. Most browsers allow you to block or delete cookies. Note that disabling essential cookies may affect website functionality.</p><h3>Third-Party Cookies</h3><p>We may use cookies from third-party services including Google Analytics, Facebook Pixel, and payment processors. These services have their own privacy policies.</p><h3>Updates to This Policy</h3><p>We may update this Cookie Policy periodically. Please check this page for the latest information.</p><h3>Contact Us</h3><p>Questions about our cookie use? Email privacy@nestifytech.com.</p>', 'publish', 'page', '2026-10-15 23:29:30', '2026-10-22 04:15:40'),
(8, 1, 'Top 10 Flagship Smartphones to Watch in 2026', 'top-10-flagship-smartphones-to-watch-in-2026', '<h2>Top 10 Flagship Smartphones to Watch in 2026</h2><p>The smartphone market is more exciting than ever in 2026. From groundbreaking camera systems to unprecedented AI capabilities, these flagship devices are pushing the boundaries of what\'s possible in your pocket.</p><h3>1. The AI-Powered Revolution</h3><p>This year\'s flagships are defined by on-device AI processing. From real-time translation to intelligent photography that anticipates your shot before you press the shutter — artificial intelligence is now the core differentiator among premium smartphones.</p><h3>2. Display Technology Breakthroughs</h3><p>Variable refresh rate displays up to 165Hz, under-display cameras with dramatically improved image quality, and foldable form factors that have finally matured into daily-driver worthy devices are all on our list.</p><h3>3. Battery Life: The Final Frontier</h3><p>Solid-state battery technology is beginning to trickle into flagship phones, promising 20-30% more capacity in the same physical space. Combined with more efficient chipsets, all-day battery life is now a minimum expectation rather than a premium feature.</p><h3>4. Camera Systems: Computational vs Hardware</h3><p>The debate between computational photography and pure optical hardware rages on, but 2026\'s best phones are finding ways to do both — offering periscope zoom up to 10x and sensor sizes that would have been unimaginable five years ago.</p><h3>5. Connectivity and Beyond 5G</h3><p>With satellite connectivity now standard on many flagships, you\'re never truly out of reach. Wi-Fi 7 brings multi-gigabit speeds that make wired connections feel redundant for most use cases.</p><p>Stay tuned to NestifyTech for our in-depth reviews of each device as they launch throughout the year.</p>', 'publish', 'blog', '2026-10-15 23:29:30', '2026-10-22 03:10:32'),
(9, 1, 'Ultrabooks vs Gaming Laptops: Finding Your Perfect Balance', 'ultrabooks-vs-gaming-laptops-finding-your-perfect-balance', '<h2>Ultrabooks vs Gaming Laptops: Finding Your Perfect Balance</h2><p>Choosing between an ultrabook and a gaming laptop is one of the most common dilemmas for laptop shoppers. Both categories have evolved significantly, and the line between them is blurring — but they still serve fundamentally different purposes.</p><h3>What Makes an Ultrabook?</h3><p>Ultrabooks prioritize portability, battery life, and build quality over raw performance. They typically feature thin-and-light chassis under 1.5kg, 15+ hours of battery life, premium materials like aluminum or carbon fiber, and processors optimized for efficiency rather than maximum throughput.</p><h3>The Gaming Laptop Proposition</h3><p>Gaming laptops, on the other hand, pack discrete GPUs that enable high-frame-rate gaming, video editing, and 3D rendering. Modern gaming laptops have improved significantly in thermal management, but the trade-off between performance and portability remains real.</p><h3>The Hybrid Category</h3><p>In 2026, a new breed of laptops blurs these boundaries. Thin gaming laptops with advanced cooling vapor chambers can deliver solid gaming performance in a 1.8kg form factor — though usually at a premium price.</p><h3>Making the Decision</h3><ul><li><strong>Choose an Ultrabook if:</strong> You travel frequently, work in office environments, prioritize battery life, and your workload is productivity-focused.</li><li><strong>Choose a Gaming Laptop if:</strong> You play AAA games, work with video production, 3D modeling, or need maximum GPU performance.</li></ul><p>Browse our curated selection of both categories at NestifyTech to find your perfect match.</p>', 'publish', 'blog', '2026-10-15 23:29:30', '2026-10-22 03:02:25'),
(10, 1, 'How Spatial Audio and Lossless Codecs Transform Everyday Listening', 'how-spatial-audio-and-lossless-codecs-transform-everyday-listening', '<h2>How Spatial Audio and Lossless Codecs Transform Everyday Listening</h2><p>The audio landscape has undergone a quiet revolution. Thanks to spatial audio and lossless streaming codecs, the gap between professional studio monitoring and consumer listening has narrowed dramatically.</p><h3>Understanding Spatial Audio</h3><p>Spatial audio, also known as 3D audio or immersive audio, uses psychoacoustic techniques to create the sensation of sound coming from all around you — including above and below. Dolby Atmos and Sony 360 Reality Audio are the two dominant formats, and they\'re now supported by major streaming services.</p><h3>Lossless Audio: What It Actually Means</h3><p>Lossless audio formats like FLAC, ALAC, and MQA preserve every bit of data from the original recording. Unlike MP3 or AAC which discard audio data deemed inaudible, lossless formats maintain the complete waveform, resulting in improved clarity, better stereo imaging, and more accurate instrument separation.</p><h3>Hardware Requirements</h3><p>To truly benefit from these technologies, you need compatible hardware: headphones with aptX Lossless or LDAC support, DACs (digital-to-analog converters) with high SNR ratings, and amplifiers capable of driving your headphones properly.</p><h3>Is the Difference Audible?</h3><p>The answer depends on your equipment, your ears, and the recording quality. In blind listening tests, trained listeners can reliably distinguish lossless from high-quality lossy formats on well-recorded material through capable headphones.</p><p>Explore our curated selection of audiophile-grade headphones and DACs at NestifyTech.</p>', 'publish', 'blog', '2026-10-15 23:29:30', '2026-10-22 03:13:07'),
(11, 1, 'Building an Intuitive Smart Home: Where to Begin', 'building-an-intuitive-smart-home-where-to-begin', '<h2>Building an Intuitive Smart Home: Where to Begin</h2><p>The promise of a smart home is compelling: lights that respond to voice commands, thermostats that learn your schedule, security cameras that send alerts to your phone, and appliances that communicate with each other seamlessly. But where do you actually start?</p><h3>Choosing Your Ecosystem</h3><p>The most important decision is which smart home ecosystem to build around. The three major platforms — Amazon Alexa, Google Home, and Apple HomeKit — each have strengths and weaknesses. Matter, the new universal protocol, is gradually making cross-ecosystem compatibility better, but your primary ecosystem still matters.</p><h3>Start with the Fundamentals</h3><p>Smart lighting is the easiest entry point. Smart bulbs or in-wall switches provide immediate, tangible benefits with relatively straightforward installation. Follow this with a smart thermostat — the energy savings alone often justify the investment within the first year.</p><h3>Security and Monitoring</h3><p>Video doorbells and indoor cameras give you visibility into your home from anywhere. Look for cameras with local storage options rather than cloud-only solutions to maintain control over your footage.</p><h3>Automation: Where the Magic Happens</h3><p>True smart home magic happens through automations: scenes that adjust multiple devices simultaneously, routines that trigger based on time or location, and conditions that make devices respond to each other intelligently.</p><h3>Getting Started</h3><p>Browse our smart home collection at NestifyTech, where we\'ve curated devices that work well together and offer genuine quality-of-life improvements.</p>', 'publish', 'blog', '2026-10-15 23:29:30', '2026-10-22 03:13:58'),
(12, 1, 'Samsung Galaxy S25 Ultra (12GB-256GB)', 'NST-82600001', '<p><strong>Product Title:</strong> Samsung Galaxy S25 Ultra (12GB-256GB)</p><p>Unlock ultimate performance with the Samsung Galaxy S25 Ultra. This powerhouse features a 6.8\" Dynamic AMOLED display for vibrant visuals, 12GB RAM and 256GB storage for seamless multitasking, and a quad-camera setup with 108MP primary sensor and 100x zoom.</p><ul><li>6.8-inch Dynamic AMOLED 2X, 120Hz display</li><li>Quad-camera with 108MP primary sensor and 100x zoom</li><li>12GB RAM, 256GB high-speed UFS 4.0 storage</li><li>Long-lasting 5000mAh battery with 45W fast charging</li><li>Integrated S-Pen stylus and titanium frame</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-29 07:03:34'),
(13, 1, 'Adidas Samba Shoes | Trending Samba (Unisex)', 'NST-1260900001', '<p><strong>Adidas Samba OG Shoes</strong></p><p>Born on the pitch, the Samba is a timeless icon of street style. This version stays true to its heritage with a soft leather upper and comfortable suede overlays.</p><ul><li>Regular fit, lace closure</li><li>Full grain leather upper with gritty suede and gold foil details</li><li>Synthetic leather lining, gum rubber midsole and outsole</li><li>Timeless iconic 3-Stripes branding</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-28 12:10:33'),
(14, 1, 'Skechers - Junior (10 Years - 14 Years)', 'NST-1260900002', '<p>The SKECHERS Retro Graph Slip-In shoes make school mornings and busy days effortless for kids. Built for everyday wear, they give little ones the comfort they want without slowing them down.</p><ul><li>Hands Free Slip-ins® design for easy step-in</li><li>Heel Pillow® keeps foot secure</li><li>Air-Cooled Memory Foam® cushioned insole</li><li>Flexible traction outsole for steady grip</li><li>Machine washable construction</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-28 12:09:58'),
(15, 1, 'HP EliteBook 840 G7 | Core i5 10th Gen | 8GB RAM | 256GB SSD', 'NST-1260900003', '<p>The HP EliteBook 840 G7 is an enterprise-class ultrabook crafted with an all-metal aluminum chassis. Powered by a 10th Gen Intel Core processor, it combines fast boot times, crisp Bang &amp; Olufsen sound, and a durable design.</p><ul><li>14.0-inch Full HD (1920x1080) IPS anti-glare display</li><li>Intel Core i5 10th Gen processor (1.6 to 4.2 GHz)</li><li>8GB DDR4 RAM, 256GB NVMe SSD</li><li>Bang &amp; Olufsen studio-quality dual speakers</li><li>Wi-Fi 6, Bluetooth 5.0, Thunderbolt 3 ports</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-28 12:09:30'),
(16, 1, 'Premium School Bags for boys girls, university, college, laptop and travel', 'NST-1260900004', '<p>Multi-purpose water-resistant travel and laptop backpack designed for school, university, and daily commute.</p><ul><li>High-grade water-repellent oxford fabric</li><li>Dedicated padded sleeve for up to 15.6-inch laptops</li><li>Ergonomic breathable mesh shoulder straps</li><li>Multiple multi-utility zippered compartments</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-28 12:09:04'),
(17, 1, 'TCL 50\" S5K QLED TV', 'NST-1260900005', '<p>Immerse yourself in cinematic 4K resolution with the TCL 50-inch S5K QLED Smart Google TV. Featuring quantum dot color technology, HDR 10, Dolby Audio, and Google Assistant voice control.</p><ul><li>50-inch 4K UHD (3840x2160) Quantum Dot QLED panel</li><li>HDR 10 and Micro Dimming for high contrast</li><li>Google TV with Chromecast built-in and Google Assistant</li><li>Dolby Audio cinematic sound system</li><li>Ultra-slim bezel-less metal aesthetics</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-29 06:46:33'),
(18, 1, 'Noise-Cancelling Headphones Pro', 'NST-1260900006', '<p>Experience audio perfection with hybrid active noise cancellation. Custom 40mm dynamic drivers deliver punchy bass and crystalline highs with 30-hour battery life.</p><ul><li>Hybrid Active Noise Cancellation with Transparency mode</li><li>40mm custom high-fidelity dynamic drivers</li><li>30 hours playback on single charge with fast USB-C charge</li><li>Ultra-comfortable memory foam ear cushions</li></ul>', 'publish', 'product', '2026-10-15 23:29:30', '2026-10-25 10:22:46'),
(19, 1, 'NestifyTech - Main Lahore', 'nestifytech-main-lahore', '', 'publish', 'store', '2026-10-25 01:19:14', '2026-10-25 01:19:14'),
(20, 1, 'How long does standard delivery take to arrive?', 'how-long-does-standard-delivery-take-to-arrive', '<p>Standard shipping typically takes <strong>3 to 5 business days</strong> within the domestic region. If you need your order expedited, we offer Express Shipping (1-2 business days) options during checkout. Tracking is provided as soon as your parcel leaves our fulfillment center.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(21, 1, 'How can I track my shipment in real time?', 'how-can-i-track-my-shipment-in-real-time', '<p>Once your order has been packed and handed over to our carrier, an automated confirmation email with your dedicated tracking number and link is sent to you. You can also view live delivery progress directly from your <strong>Account Dashboard</strong> under the \"Orders\" section.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(22, 1, 'Can I edit or cancel an order after placing it?', 'can-i-edit-or-cancel-an-order-after-placing-it', '<p>To ensure lightning-fast dispatch, orders enter processing almost immediately. If you need to make corrections to your shipping address or cancel an item, please reach out to our 24/7 customer support within <strong>60 minutes</strong> of placing the order.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(23, 1, 'What payment methods and currencies do you support?', 'what-payment-methods-and-currencies-do-you-support', '<p>We accept all major credit and debit cards including <strong>Visa, MasterCard, and American Express</strong>, along with PayPal, Apple Pay, Google Pay, and Stripe secure checkout. All charges are securely processed in USD or your local detected currency.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(24, 1, 'Is my payment information and credit card data secure?', 'is-my-payment-information-and-credit-card-data-secure', '<p>Absolutely. Every financial transaction is safeguarded by <strong>256-bit SSL encryption</strong> and processed through tier-1 PCI-DSS Level 1 compliant financial gateways. We never store, log, or share your sensitive credit card information on our servers.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(25, 1, 'What is your return and exchange policy?', 'what-is-your-return-and-exchange-policy', '<p>We offer a straightforward <strong>30-day return policy</strong>. If you are not completely satisfied with your purchase, you may return the item in its original condition and packaging for a full refund or replacement. Defective items qualify for complimentary return shipping.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(26, 1, 'How long does it take to receive my refund?', 'how-long-does-it-take-to-receive-my-refund', '<p>Once your returned item arrives at our warehouse and passes quality inspection (usually within 24-48 hours), your refund will be processed back to your original payment method. Depending on your bank or card issuer, funds will appear in your statement within <strong>3 to 7 business days</strong>.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(27, 1, 'Do all electronic devices include a manufacturer warranty?', 'do-all-electronic-devices-include-a-manufacturer-warranty', '<p>Yes! Every brand-new electronic device comes standard with a minimum <strong>1-year official manufacturer warranty</strong> covering hardware malfunctions and defects. You can also opt for extended protection warranties during checkout.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(28, 1, 'Are all products 100% authentic and genuine?', 'are-all-products-100-authentic-and-genuine', '<p>We are an authorized direct partner and distributor for all brands featured in our store. Every product is <strong>100% genuine, brand new, factory sealed</strong>, and accompanied by authentic serial numbers and documentation.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(29, 1, 'How do I reset my password or recover my account?', 'how-do-i-reset-my-password-or-recover-my-account', '<p>Click on the \"Forgot Password\" link on the login page, enter your registered email address, and you will immediately receive a secure password reset link. For any other login difficulties, our support team can verify your identity and restore access.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(30, 1, 'How can I contact customer service for help?', 'how-can-i-contact-customer-service-for-help', '<p>Our support representatives are standing by 24/7. You can reach us via our live chat widget on the website, email us at <strong>support@nestifytech.com</strong>, or call our toll-free phone line at <strong>+1 (800) 123-4567</strong>.</p>', 'publish', 'faq', '2026-10-25 09:36:56', '2026-10-25 09:36:56'),
(31, 1, 'NestifyTech - Okara', 'nestifytech-okara', 'hi its there', 'publish', 'store', '2026-10-28 10:35:58', '2026-11-02 06:46:22'),
(32, 5, 'Samsung Galaxy s22 ultra | 12GB Ram | 128GB, 256GB, 512GB | official PTA approved | without box', 'NST-13242145', '<p><br></p><p>Feature | Details</p><p>------------------|------------------------------------------------</p><p>Screen | 6.8-inch Quad HD+ AMOLED, 120Hz refresh rate</p><p>Camera (Back) | 108MP + 12MP (ultrawide) + 10MP + 10MP</p><p>Camera (Front) | 40MP</p><p>Battery | 5000 mAh, Fast Charging (45W)</p><p>Storage Options | 128GB / 256GB / 512GB / 1TB</p><p>RAM | 8GB or 12GB</p><p>Processor | Snapdragon 8 Gen 1 or Exynos 2200</p><p>S Pen | Built-in stylus (like Note series)</p><p>Water Resistance | Yes (IP68 certified)</p><p>- Big 6.8-inch screen with 120Hz refresh rate for smooth display</p><p>- 108MP main camera + 3 extra cameras (zoom and wide shots)</p><p>- 40MP front camera for selfies</p><p>- 5000 mAh battery with 45W fast charging</p><p>- Storage options: 128GB, 256GB, 512GB, or 1TB</p><p>- RAM: 8GB or 12GB for faster performance</p><p>- Powerful processors: Snapdragon 8 Gen 1 or Exynos 2200</p><p>- Built-in S Pen (stylus) for writing or drawing</p><p>- Water and dust resistant (IP68 rating)</p>', 'publish', 'product', '2026-11-02 12:09:08', '2026-11-03 03:55:00');
